define({"topics":[{"title":"B0 B1 Map Troubleshooting Guide","shortdesc":"<p class=\"shortdesc\">When you find shadings in the image, please follow the procedure below and setup B0 map and B1 map protocols.<\/p>","href":"t_B0B1MapTroubleshootingGuide.html","attributes":{"data-id":"id_2039880"},"menu":{"hasChildren":false},"tocID":"id_2039880-d46e57602","topics":[]},{"title":"Coherent noise tool kit","shortdesc":"<p class=\"shortdesc\">Use the coherent noise tool kit to isolate coherent noise sources using a transmitter (Tx), receiver (Rx), and antennas. This procedure has instructions for setting up and using the kit.<\/p>","href":"t_CoherentNoiseToolKit_Parent.html","attributes":{"data-id":"id_2044606"},"menu":{"hasChildren":true},"tocID":"id_2044606-d46e57710","next":"id_2044606-d46e57710"},{"title":"Coherent noise tool kit items","shortdesc":"<p class=\"shortdesc\">Additional information about the transmitter (Tx), receiver (Rx), and antennas in the coherent noise tool kit.<\/p>","href":"r_CoherentNoiseToolKitItems.html","attributes":{"data-id":"id_2046266"},"menu":{"hasChildren":false},"tocID":"id_2046266-d46e58675","topics":[]},{"title":"EPI Ghosting Checks","href":"c_EPI-Ghosting-Checks_14146588.html","attributes":{"data-id":"id_15667017"},"menu":{"hasChildren":false},"tocID":"id_15667017-d46e58782","topics":[]}]});